\begin{align*}
\frac{12}{x \cdot x} \cdot \frac{x^4}{14x}\cdot \frac{35}{3x} &= \frac{12x^2}{x^2} \cdot \frac{x^4}{14x} \cdot \frac{35x}{3x} \\
&= \frac{12x^5}{14} \\
